1	% =====================================================================
2	%  style.sty: design system for „מאחורי הפלייליסט" (Behind the Playlist)
3	%  Owner: Boss. Writers use ONLY the commands documented in the
4	%  "WRITER INTERFACE" block below; do not add packages in chapter files.
5	%  Engine: XeLaTeX. bidi (loaded by polyglossia) must come LAST, so every
6	%  package that bidi patches is loaded before it.
7	% =====================================================================
8	\NeedsTeXFormat{LaTeX2e}
9	\ProvidesPackage{style}[2026/11/14 Behind the Playlist design]
10	
11	% ---------- page ----------------------------------------------------
12	\RequirePackage[a4paper,top=2.6cm,bottom=3.0cm,inner=2.5cm,outer=2.5cm,
13	  headsep=0.8cm,footskip=1.3cm]{geometry}
14	\RequirePackage{setspace}
15	\setstretch{1.22}
16	\setlength{\parskip}{0.45em}
17	\setlength{\parindent}{0pt}
18	\raggedbottom
19	
20	% ---------- packages bidi patches (must precede polyglossia/bidi) ----
21	\RequirePackage{amsmath}
22	\RequirePackage[table]{xcolor}
23	\RequirePackage{graphicx}
24	\RequirePackage{array,tabularx,booktabs}
25	\RequirePackage{caption}
26	\RequirePackage{enumitem}
27	\RequirePackage{titlesec}
28	\RequirePackage{fancyhdr}
29	\RequirePackage{zref-totpages}
30	\RequirePackage{tikz}
31	\usetikzlibrary{arrows.meta,positioning,calc,shapes.misc}
32	\RequirePackage[skins,breakable]{tcolorbox}
33	\RequirePackage{csquotes}
34	\RequirePackage[hidelinks]{hyperref}
35	
36	% ---------- fonts & languages ----------------------------------------
37	\RequirePackage{fontspec}
38	\RequirePackage{polyglossia}
39	\setmainlanguage{hebrew}
40	\setotherlanguage{english}
41	% biblatex must follow polyglossia (biblatex error otherwise)
42	\RequirePackage[backend=biber,style=numeric,sorting=nyt,maxbibnames=6,
43	  giveninits=true,url=true,doi=true,isbn=false,eprint=false]{biblatex}
44	% Latin + math text: New Peninim and Arial Hebrew have no Latin glyphs (PRD §6).
45	\setmainfont{Times New Roman}
46	\setsansfont{Arial}
47	\newfontfamily\englishfont{Times New Roman}
48	\newfontfamily\hebrewfont{New Peninim MT}[Script=Hebrew,Scale=1.12,
49	  BoldFont={New Peninim MT Bold},
50	  ItalicFont={New Peninim MT Inclined},
51	  BoldItalicFont={New Peninim MT Bold Inclined}]
52	\newfontfamily\hebrewfontsf{Arial Hebrew}[Script=Hebrew]
53	\newfontfamily\headfont{Arial Hebrew}[Script=Hebrew]
54	
55	% ---------- palette (also used in figures/noa_week.py) ----------------
56	\definecolor{ink}{HTML}{1E3A4C}      % headings, lab boxes
57	\definecolor{teal}{HTML}{2A7F84}     % brand: "בקצרה", graph plays
58	\definecolor{coral}{HTML}{D8664B}    % accent: "רגע, זה אמיתי?", graph skips
59	\definecolor{muted}{HTML}{6B7280}    % tags, captions, rules
60	\definecolor{paper}{HTML}{FBF6EE}    % fictional scene background
61	\definecolor{rulegrey}{HTML}{E5E7EB}
62	\colorlet{tealsoft}{teal!7}
63	\colorlet{coralsoft}{coral!8}
64	\colorlet{inksoft}{ink!5}
65	
66	% ---------- TikZ: Hebrew node text (PRD §6 TikZ RTL rule) -------------
67	% Use [heb] on uncoloured nodes that contain Hebrew words; for coloured Hebrew text use \hebcolor{color}{text} (defined below).
68	\tikzset{heb/.style={execute at begin node=\beginR, execute at end node=\endR}}
69	
70	% ---------- chapter openers: "רצועה 01" + equalizer -------------------
71	\newcommand{\eqbars}[1]{% #1 = chapter number, seeds bar heights
72	  \begin{tikzpicture}[baseline=0pt]
73	    \foreach \i in {0,...,17}{
74	      \pgfmathsetmacro{\h}{0.12+0.5*abs(sin(37*\i+53*#1))}
75	      \fill[teal!70] (\i*0.17,0) rectangle ++(0.09,\h);}
76	  \end{tikzpicture}}
77	\newcommand{\tracklabel}[1]{\textcolor{coral}{\headfont\small רצועה\enspace\ifnum#1<10 0\fi#1}}
78	\titleformat{\chapter}[display]
79	  {\headfont\color{ink}}
80	  {\tracklabel{\thechapter}\hfill\eqbars{\thechapter}}
81	  {6pt}
82	  {\bfseries\fontsize{24}{30}\selectfont}
83	  [\vspace{4pt}{\color{rulegrey}\titlerule[0.8pt]}]
84	\titleformat{name=\chapter,numberless}[display]
85	  {\headfont\color{ink}}{}{0pt}
86	  {\bfseries\fontsize{24}{30}\selectfont}
87	  [\vspace{4pt}{\color{rulegrey}\titlerule[0.8pt]}]
88	\titlespacing*{\chapter}{0pt}{-18pt}{16pt}
89	\titleformat{\section}{\headfont\bfseries\large\color{teal}}{}{0pt}{}
90	\titlespacing*{\section}{0pt}{12pt}{4pt}
91	\setcounter{secnumdepth}{0}   % chapters numbered, sections not
92	\setcounter{tocdepth}{0}      % TOC lists chapters only
93	
94	% ---------- header / footer: a "player" progress bar ------------------
95	\newcommand{\playerbar}{%
96	  \begin{tikzpicture}
97	    \pgfmathsetmacro{\tot}{max(\ztotpages,1)}
98	    \pgfmathsetmacro{\pf}{min(\thepage/\tot,1)}
99	    \def\W{\textwidth-2.2cm}
100	    \draw[rulegrey,line width=1.4pt,line cap=round] (1.1cm,0) -- (\textwidth-1.1cm,0);
101	    \draw[teal,line width=1.4pt,line cap=round]
102	      (\textwidth-1.1cm,0) -- ($(\textwidth-1.1cm,0)-(\pf*\textwidth-\pf*2.2cm,0)$);
103	    \fill[teal] ($(\textwidth-1.1cm,0)-(\pf*\textwidth-\pf*2.2cm,0)$) circle (2.6pt);
104	    \node[font=\sffamily\scriptsize,text=ink,anchor=east] at (\textwidth,0) {\thepage};
105	    \node[font=\sffamily\scriptsize,text=muted,anchor=west] at (0,0) {\ztotpages};
106	  \end{tikzpicture}}
107	\pagestyle{fancy}
108	\fancyhf{}
109	\fancyhead[R]{\headfont\footnotesize\color{muted}מאחורי הפלייליסט}
110	\fancyhead[L]{\headfont\footnotesize\color{muted}\leftmark}
111	\fancyfoot[C]{\playerbar}
112	\renewcommand{\headrulewidth}{0pt}
113	\renewcommand{\chaptermark}[1]{\markboth{#1}{}}
114	\fancypagestyle{plain}{\fancyhf{}\fancyfoot[C]{\playerbar}\renewcommand{\headrulewidth}{0pt}}
115	
116	% ---------- captions ---------------------------------------------------
117	\captionsetup{font={small,sf},labelfont={bf,color=teal},labelsep=colon,
118	  justification=centering,skip=6pt}
119	\DeclareCaptionFont{hsf}{\hebrewfontsf}
120	\captionsetup{font+=hsf}
121	
122	% ---------- lists --------------------------------------------------------
123	\setlist{itemsep=2pt,topsep=4pt}
124	\setlist[itemize]{label={\tikz[baseline=-0.55ex]\fill[teal] (0,0) circle (1.7pt);}} % New Peninim has no U+2022
125	
126	% ---------- boxes ---------------------------------------------------------
127	% #3 (optional) = tag pill shown at the far (left) end of the title line.
128	% A paragraph must never START with a TikZ box: bidi then sets it LTR (tag lands on the left).
129	\newcommand{\boxtitle}[3][]{{\headfont\bfseries\color{#2}#3}\ifx\relax#1\relax\else\hfill#1\fi\par\smallskip}
130	\tcbset{bookbase/.style={enhanced,breakable,boxrule=0pt,arc=1.6mm,
131	  left=4mm,right=5mm,top=3mm,bottom=3mm,before skip=10pt,after skip=10pt}}
132	% NB (verified 2026-11-14 at glyph level): inside a [heb] node ANY colour change
133	% (text=<color> or \color in the content) renders the text WHITE. For coloured Hebrew
134	% node text, do not use [heb]; put the colour OUTSIDE the RTL segment, as in \hebcolor.
135	\newcommand{\hebcolor}[2]{\textcolor{#1}{\beginR#2\endR}}
136	\DeclareRobustCommand{\tagpill}[1]{\tikz[baseline=(t.base)]\node[draw=muted,dashed,rounded corners=2pt,
137	  inner xsep=3.5pt,inner ysep=2.5pt,font=\headfont\footnotesize](t){\hebcolor{muted}{#1}};}
138	
139	% ===================== WRITER INTERFACE =====================
140	% \begin{scene} ... \end{scene}            fictional scene with Noa (titled "סצנה", auto-tagged "בדיוני")
141	% \begin{inshort} ... \end{inshort}         "בקצרה" takeaways box (teal)
142	% \begin{lab}{<title>} ... \end{lab}        "מעבדה" formula / worked example (ink), auto-tagged "דוגמה לימודית"
143	% \begin{realitycheck} ... \end{realitycheck}  "רגע, זה אמיתי?" research vs. myth / attributed platform claim (coral)
144	% \fictional          inline tag "נתונים בדיוניים" (use mid-sentence or in captions; never as the first thing in a paragraph)
145	% \educational        inline tag "דוגמה לימודית"
146	% \term{מונח}{English term}   first use of a technical term: bold Hebrew + (English)
147	% \en{English text}    English words inside Hebrew text
148	% \cite[<postnote>]{key1,key2}  citation, printed as an LTR [n] unit
149	% Figures/tables: standard figure/table environments with \caption and \label.
150	\newtcolorbox{scene}{bookbase,colback=paper,borderline east={2pt}{0pt}{coral!60},
151	  before upper={\boxtitle[\tagpill{בדיוני}]{coral!80!ink}{סצנה}}}
152	\newtcolorbox{inshort}{bookbase,colback=tealsoft,borderline east={3pt}{0pt}{teal},
153	  before upper={\boxtitle{teal}{בקצרה}}}
154	\newtcolorbox{lab}[1]{bookbase,colback=inksoft,borderline east={3pt}{0pt}{ink},
155	  before upper={\boxtitle[\tagpill{דוגמה לימודית}]{ink}{מעבדה: #1}}}
156	\newtcolorbox{realitycheck}{bookbase,colback=coralsoft,borderline east={3pt}{0pt}{coral},
157	  before upper={\boxtitle{coral}{רגע, זה אמיתי?}}}
158	\DeclareRobustCommand{\fictional}{\tagpill{נתונים בדיוניים}}
159	\DeclareRobustCommand{\educational}{\tagpill{דוגמה לימודית}}
160	\newcommand{\term}[2]{\textbf{\textcolor{ink}{#1}}~(\en{#2})}
161	\newcommand{\en}[1]{\textenglish{#1}}
162	% Citations as a single LTR English-font unit (postnotes like "p.~3" need Latin glyphs) so "[3, 7]" never reorders inside RTL text.
163	\AtBeginDocument{%
164	  \let\bookorigcite\cite
165	  \RenewDocumentCommand{\cite}{o m}{\textenglish{\IfValueTF{#1}{\bookorigcite[#1]{#2}}{\bookorigcite{#2}}}}}
166	\endinput
