  \item $\lVert\mathbf{a}\rVert$ ו-$\lVert\mathbf{b}\rVert$: האורך של כל וקטור. מעלים כל מספר בריבוע, מחברים, ומוציאים שורש.
  \item $\theta$: הזווית בין שני הווקטורים. ככל שהיא קטנה יותר, הטעמים „מצביעים" לאותו כיוון.
  \item $\cos(\theta)$: התוצאה. כשכל המספרים אינם שליליים, כמו מספרי השמעות, היא בין 0 ל-1. ‏1 פירושו טעם זהה ביחסים, ו-0 פירושו שאין שום שיר משותף.
\end{itemize}

\textbf{דוגמה מחושבת.} הטבלה הבאה מראה כמה פעמים כל אחד שמע שלושה שירים בשבוע אחד, והיא כולה נתונים בדיוניים \fictional.
\begin{center}
\begin{tabular}{@{}lccc@{}}
\toprule
מאזין/ה & שיר א & שיר ב & שיר ג\\
\midrule
נועה ($\mathbf{n}$) & 5 & 2 & 1\\
יוני ($\mathbf{y}$) & 4 & 3 & 0\\
מאיה ($\mathbf{m}$) & 1 & 0 & 5\\
\bottomrule
\end{tabular}
\end{center}

\textbf{נועה מול יוני.} המכפלה הסקלרית, האורכים והתוצאה:
\[\mathbf{n}\cdot\mathbf{y}=5\cdot4+2\cdot3+1\cdot0=26\]
\[\lVert\mathbf{n}\rVert=\sqrt{5^2+2^2+1^2}=\sqrt{30}\approx5.48,\qquad \lVert\mathbf{y}\rVert=\sqrt{4^2+3^2+0^2}=\sqrt{25}=5\]
\[\cos(\theta)=\frac{26}{\sqrt{30}\cdot5}\approx\frac{26}{27.39}\approx0.95\]

\textbf{נועה מול מאיה.} אותו תהליך:
\[\mathbf{n}\cdot\mathbf{m}=5\cdot1+2\cdot0+1\cdot5=10\]
\[\lVert\mathbf{m}\rVert=\sqrt{1^2+0^2+5^2}=\sqrt{26}\approx5.10\]
\[\cos(\theta)=\frac{10}{\sqrt{30}\cdot\sqrt{26}}\approx\frac{10}{27.93}\approx0.36\]

